N, M, K = map(int, input().split())
A = deque(map(int, input().split()))
B = deque(map(int, input().split()))

read_time = 0
read_num = 0

while not(len(A)==0 and len(B)==0) and read_time<=K:
    if len(A)==0 and len(B)==0:
        break
    elif len(A)==0:
        r = B.popleft()
        if K>=read_time+r:
            read_num += 1
        continue
    elif len(B)==0:
        r = A.popleft()
        if K>=read_time+r:
            read_num += 1
        continue
    if(A[0]<B[0]):
        r = A.popleft()
        if K>=read_time+r:
            read_num += 1
    else:
        r = B.popleft()
        if K>=read_time+r:
            read_num += 1
    read_time += r
