import numpy

def main():
  _, _, k = map(int, input().strip().split())
  la = numpy.cumsum(list(map(int, input().strip().split())))
  lb = numpy.cumsum(list(map(int, input().strip().split())) + [10**9+5])

  def bs(x):
    s, t = 0 , len(lb)
    while t - s >= 2:
      m = (s + t) // 2
      if lb[m] > x:
        t = m
      else:
        s = m
    return s + 1

  ans = 0
  for i, a in enumerate(la, 1):
    if k - a >= 0:
      ans = max(ans, i + bs(k - a))
  print(ans)

if __name__=='__main__':
  main()

